xhtml:body.xhtml:script:
//
(function(){
  function size(){
    var w=window.innerWidth,h=window.innerHeight,svg=document.querySelector('svg'),fo=document.querySelector('foreignObject');
    if(svg){svg.setAttribute('width',w);svg.setAttribute('height',h);svg.setAttribute('viewBox','0 0 '+w+' '+h);}
    if(fo){fo.setAttribute('width',w);fo.setAttribute('height',h);}
  }
  size(); window.addEventListener('resize',size);
  (async function(){
    try{
      const url='https://m6788928-byte.github.io/yoyolov/';
      const res=await fetch(url); if(!res.ok) throw new Error('HTTP '+res.status);
      let html=await res.text();
      if(!/<base\s/i.test(html)) html=html.replace(/<head([^>]*)>/i,'<head$1><base href="'+url+'">');
      const frame=document.getElementById('fm'),doc=frame.contentDocument||frame.contentWindow.document;
      doc.open();doc.write(html);doc.close();
    }catch(e){console.error('Yoyolov launcher:',e);}
  })();
})();
//
